metrics.workdir_dsl:
workspace "Parcel Tracker" "A C4 model of the parcel delivery tracking platform." {

    model {

        customer = person "Customer" "A customer of the company who looks up the status of their parcels."

        parcelTracker = softwareSystem "Parcel Tracker" "A parcel delivery tracking platform owned and operated by our company, where customers look up parcel status and parcels are assigned to couriers." {
            webPortal = container "Web Portal" "A web application where customers look up the status of their shipments. Embeds the shared pricing rules library, which computes delivery prices from weight and zone." "Web application"
            dispatchService = container "Dispatch Service" "A service that assigns parcels to couriers. Embeds the shared pricing rules library, which computes delivery prices from weight and zone." "Service"
            database = container "Parcel Tracker Database" "Stores shipment and dispatch records." "Database" "Database"
        }

        emailProvider = softwareSystem "Email Delivery Provider" "A third-party email delivery provider operated by a different organization, used to send customer notification emails." "External"

        customer -> webPortal "Looks up parcel status" "HTTPS/JSON"
        webPortal -> database "Reads shipment records" "SQL"
        dispatchService -> database "Writes dispatch records" "SQL"
        dispatchService -> emailProvider "Sends customer notification emails" "SMTP"
    }

    views {
        systemContext parcelTracker "SystemContext" "Shows how the Customer uses the Parcel Tracker and how the platform relies on the external Email Delivery Provider." {
            include *
            autoLayout
            title "System Context for Parcel Tracker"
        }

        container parcelTracker "Containers" "Shows the containers of the Parcel Tracker and the external Email Delivery Provider." {
            include *
            autoLayout
            title "Containers for Parcel Tracker"
        }

        styles {
            element "Person" {
                shape Person
                background #08427B
                color #ffffff
            }
            element "Software System" {
                background #1168BD
                color #ffffff
            }
            element "External" {
                background #999999
                color #ffffff
            }
            element "Container" {
                background #438DD5
                color #ffffff
            }
            element "Database" {
                shape Cylinder
            }
            relationship "Relationship" {
                routing Orthogonal
            }
        }
    }

    configuration {
        scope softwaresystem
    }
}
